1	/**
2	 * @module features/tv-dashboard/model/useTvDashboardData
3	 *
4	 * Hook principal da Torre de Controle da Operação (painel TV `/tv`).
5	 *
6	 * Paraleliza as fontes de dados via React Query:
7	 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
8	 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
9	 * - comparativos: vs DIA ANTERIOR (principal, v3 — base pró-rateada p/ canal
10	 *   live) e vs MESMO DIA da semana passada (secundário);
11	 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
12	 * - alertas de estoque NOMEADOS (`estoque` × `produtos_master.ativo = true`,
13	 *   restritos ao setor de produtos vendáveis — `TV_ALERT_SETOR`);
14	 * - heartbeat + FEED nomeado de movimentações (`movimentacoes` de hoje);
15	 * - perdas no período do filtro global (`perdas`, R$ + itens + delta);
16	 * - compras no período (`notas_fiscais`, "gasto até hoje" + delta);
17	 * - produção da fábrica (`daily_production` com loja_id NULL).
18	 *
19	 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
20	 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
21	 * defasado; tipo "Fabrica" = card de fábrica).
22	 */
23	
24	import { useMemo } from 'react';
25	import { useQuery } from '@tanstack/react-query';
26	import { supabase } from '@/integrations/supabase/client';
27	import type {
28	  TvComprasSummary,
29	  TvDateRange,
30	  TvException,
31	  TvFactoryData,
32	  TvFactoryProduction,
33	  TvFreshness,
34	  TvMovementSummary,
35	  TvNetworkSummary,
36	  TvPerdasSummary,
37	  TvPeriod,
38	  TvRecentMove,
39	  TvSalesChannel,
40	  TvSalesSnapshot,
41	  TvStoreData,
42	  TvExceptionsResult,
43	} from './types';
44	import {
45	  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
46	  TV_FACTORY_HOURS,
47	  TV_MINI_FEED_SIZE,
48	  addDays,
49	  aggregateCompras,
50	  aggregateMovements,
51	  aggregatePerdas,
52	  buildFreshness,
53	  buildNoMovementException,
54	  buildRecentMoves,
55	  buildStockExceptions,
56	  buildStockSummary,
57	  classifyStoreRag,
58	  fetchAllPages,
59	  parseIsoDateLocal,
60	  pctOfFullDayTarget,
61	  pctOfProRataTarget,
62	  periodRange,
63	  previousPeriodRange,
64	  proRataDayBase,
65	  rangeToLocalDayBounds,
66	  relativeDelta,
67	  remapFlashLojaIds,
68	  sortAndLimitExceptions,
69	  sortCriticalItems,
70	  toIsoDateLocal,
71	  weekOverWeekDelta,
72	  type ComprasByLoja,
73	  type FlashRow,
74	  type MovementAggregate,
75	  type MovementFeedRow,
76	  type PerdasAggregate,
77	  type PerdasByLoja,
78	  type StockDetail,
79	  type StockRow,
80	} from './tvMath';
81	import { useMinuteClock } from './useMinuteClock';
82	
83	// ─────────────────────────────────────────────────────────────────────────────
84	// Query keys + intervalos (exportados para o useTvRealtime invalidar)
85	// ─────────────────────────────────────────────────────────────────────────────
86	
87	/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
88	export const tvDashboardKeys = {
89	  all: ['tv-dashboard'] as const,
90	  context: () => [...tvDashboardKeys.all, 'context'] as const,
91	  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
92	  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
93	  /** Vendas de referência Degust (ontem + mesmo dia da semana passada). */
94	  referenceSales: () => [...tvDashboardKeys.all, 'reference-sales'] as const,
95	  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
96	  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
97	  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
98	  /** Feed nomeado de movimentações de hoje (mini-feed "AGORA"). */
99	  movementFeed: () => [...tvDashboardKeys.all, 'movement-feed'] as const,
100	  /** Prefixo das perdas (invalidar TODOS os períodos de uma vez). */
101	  perdasRoot: () => [...tvDashboardKeys.all, 'perdas'] as const,
102	  perdas: (period: TvPeriod) => [...tvDashboardKeys.perdasRoot(), period] as const,
103	  /** Prefixo das compras (invalidar TODOS os períodos de uma vez). */
104	  comprasRoot: () => [...tvDashboardKeys.all, 'compras'] as const,
105	  compras: (period: TvPeriod) => [...tvDashboardKeys.comprasRoot(), period] as const,
106	  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
107	  /** Prefixo do drill-down por loja (invalidar todas as lojas/ranges). */
108	  storeDetailRoot: () => [...tvDashboardKeys.all, 'store-detail'] as const,
109	  storeDetail: (lojaId: number, range: TvDateRange) =>
110	    [...tvDashboardKeys.storeDetailRoot(), lojaId, range.from, range.to] as const,
111	};
112	
113	// ─────────────────────────────────────────────────────────────────────────────
114	// Filtros canônicos de NF de compra (mesmo critério do módulo notas-fiscais)
115	// ─────────────────────────────────────────────────────────────────────────────
116	
117	/**
118	 * Status de NF que CONTAM como compra — mesmo critério do DRE
119	 * (`features/financeiro/ui/DREReport.tsx`): tudo menos `erro`. O campo de
120	 * data canônico é `data_nota` (emissão), idem DRE e filtro "data da nota"
121	 * da página de NFs.
122	 */
123	export const NF_COUNTED_STATUSES = ['processada', 'processando'] as const;
124	
125	/**
126	 * NFs de transferência interna (fornecedor "Momma Doces") NÃO são compra —
127	 * mesma exclusão da lista do módulo notas-fiscais (transferência ≠ NF de
128	 * compra; pertencem à aba Transferências).
129	 */
130	export const NF_TRANSFER_SUPPLIER_PATTERN = '%momma doces%';
131	
132	/** Intervalos de atualização (ms) por classe de dado. */
133	export const TV_QUERY_INTERVALS = {
134	  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
135	  liveMs: 60_000,
136	  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
137	  slowMs: 300_000,
138	} as const;
139	
140	// ─────────────────────────────────────────────────────────────────────────────
141	// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
142	// ─────────────────────────────────────────────────────────────────────────────
143	
144	/** Loja ativa carregada no contexto do painel. */
145	export interface TvLoja {
146	  id: number;
147	  nome: string;
148	  tipo: string | null;
149	}
150	
151	/** Contexto runtime do painel (lojas + canais) — reusado pelo drill-down. */
152	export interface TvContext {
153	  lojas: TvLoja[];
154	  /** Lojas com venda live (existem em `degust_stores`). */
155	  degustLojaIds: Set<number>;
156	  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
157	  degustCodeToLoja: Map<number, number>;
158	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
159	  linxLojaIds: number[];
160	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
161	  factoryLojaId: number | null;
162	}
163	
164	function isFactoryTipo(tipo: string | null): boolean {
165	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
166	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
167	}
168	
169	/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
170	export async function fetchTvContext(): Promise<TvContext> {
171	  const [lojasRes, degustRes] = await Promise.all([
172	    supabase
173	      .from('lojas')
174	      .select('id, nome, tipo')
175	      .eq('ativo', true)
176	      .order('id'),
177	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
178	  ]);
179	  if (lojasRes.error) throw lojasRes.error;
180	  if (degustRes.error) throw degustRes.error;
181	
182	  const lojas: TvLoja[] = lojasRes.data ?? [];
183	  const degustLojaIds = new Set<number>();
184	  const degustCodeToLoja = new Map<number, number>();
185	  for (const row of degustRes.data ?? []) {
186	    degustLojaIds.add(row.loja_id);
187	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
188	  }
189	
190	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
191	  const linxLojaIds = lojas
192	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
193	    .map((l) => l.id);
194	
195	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
196	}
197	
198	// ─────────────────────────────────────────────────────────────────────────────
199	// Vendas live (edge degust-pos-financial / flash-vendas)
200	// ─────────────────────────────────────────────────────────────────────────────
201	
202	/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
203	interface DegustPosFinancialResponse {
204	  flash?: Array<{
205	    loja_id: number;
206	    nome_loja: string;
207	    total_vendas: number;
208	    total_cupons: number;
209	    ticket_medio: number;
210	    qtd_produtos: number;
211	    caixa_aberto: boolean;
212	    ultima_atualizacao: string | null;
213	  }>;
214	}
215	
216	async function fetchLiveSales(ctx: TvContext): Promise<FlashRow[]> {
217	  const today = toIsoDateLocal(new Date());
218	  const { data, error } = await supabase.functions.invoke<DegustPosFinancialResponse>(
219	    'degust-pos-financial',
220	    { body: { startDate: today, endDate: today } },
221	  );
222	  if (error) throw error;
223	  const flash: FlashRow[] = (data?.flash ?? []).map((f) => ({
224	    loja_id: f.loja_id,
225	    nome_loja: f.nome_loja,
226	    total_vendas: f.total_vendas,
227	    total_cupons: f.total_cupons,
228	    ticket_medio: f.ticket_medio,
229	    caixa_aberto: f.caixa_aberto,
230	    ultima_atualizacao: f.ultima_atualizacao,
231	  }));
232	  return remapFlashLojaIds(flash, ctx.degustCodeToLoja, ctx.degustLojaIds);
233	}
234	
235	// ─────────────────────────────────────────────────────────────────────────────
236	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
237	// ─────────────────────────────────────────────────────────────────────────────
238	
239	interface LaggedSales {
240	  lojaId: number;
241	  /** Último dia com venda registrada (YYYY-MM-DD). */
242	  dataReferencia: string;
243	  valor: number;
244	  quantidade: number;
245	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
246	  valorSemanaAnterior: number | null;
247	  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
248	  valorDiaAnterior: number | null;
249	}
250	
251	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
252	  // 1) Último dia com dado para a loja
253	  const { data: latest, error: latestErr } = await supabase
254	    .from('historico_vendas')
255	    .select('data')
256	    .eq('loja_id', lojaId)
257	    .order('data', { ascending: false })
258	    .limit(1);
259	  if (latestErr) throw latestErr;
260	  const refDate = latest?.[0]?.data;
261	  if (!refDate) return null;
262	
263	  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
264	  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));
265	
266	  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
267	  //    comparativo PRINCIPAL v3; mesma semana = secundário)
268	  const [curRes, weekRes, dayRes] = await Promise.all([
269	    supabase
270	      .from('historico_vendas')
271	      .select('valor_total, quantidade')
272	      .eq('loja_id', lojaId)
273	      .eq('data', refDate)
274	      .limit(2000),
275	    supabase
276	      .from('historico_vendas')
277	      .select('valor_total')
278	      .eq('loja_id', lojaId)
279	      .eq('data', weekAgoDate)
280	      .limit(2000),
281	    supabase
282	      .from('historico_vendas')
283	      .select('valor_total')
284	      .eq('loja_id', lojaId)
285	      .eq('data', dayBeforeDate)
286	      .limit(2000),
287	  ]);
288	  if (curRes.error) throw curRes.error;
289	  if (weekRes.error) throw weekRes.error;
290	  if (dayRes.error) throw dayRes.error;
291	
292	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
293	  const quantidade = (curRes.data ?? []).reduce(
294	    (s, r) => s + (r.quantidade ?? 0),
295	    0,
296	  );
297	  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
298	    const list = rows ?? [];
299	    return list.length > 0
300	      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
301	      : null;
302	  };
303	
304	  return {
305	    lojaId,
306	    dataReferencia: refDate,
307	    valor,
308	    quantidade,
309	    valorSemanaAnterior: sumOrNull(weekRes.data),
310	    valorDiaAnterior: sumOrNull(dayRes.data),
311	  };
312	}
313	
314	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
315	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
316	  return results.filter((r): r is LaggedSales => r !== null);
317	}
318	
319	// ─────────────────────────────────────────────────────────────────────────────
320	// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
321	// passada (secundário) — uma única query em degust_vendas_diarias
322	// ─────────────────────────────────────────────────────────────────────────────
323	
324	interface DegustReferenceSales {
325	  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
326	  yesterday: Map<number, number>;
327	  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
328	  lastWeek: Map<number, number>;
329	}
330	
331	async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
332	  const yesterday = new Map<number, number>();
333	  const lastWeek = new Map<number, number>();
334	  const ids = [...ctx.degustLojaIds];
335	  if (ids.length === 0) return { yesterday, lastWeek };
336	  const now = new Date();
337	  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
338	  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
339	  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
340	  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
341	  const rows = await fetchAllPages((from, to) =>
342	    supabase
343	      .from('degust_vendas_diarias')
344	      .select('loja_id, valor_total, data')
345	      .in('data', [yesterdayDate, lastWeekDate])
346	      .in('loja_id', ids)
347	      .order('id')
348	      .range(from, to),
349	  );
350	  for (const row of rows) {
351	    const target = row.data === yesterdayDate ? yesterday : lastWeek;
352	    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
353	  }
354	  return { yesterday, lastWeek };
355	}
356	
357	// ─────────────────────────────────────────────────────────────────────────────
358	// Metas (loja × dia da semana, convenção JS Date.getDay(): 0=domingo)
359	// ─────────────────────────────────────────────────────────────────────────────
360	
361	async function fetchMetas(): Promise<Map<string, number>> {
362	  const { data, error } = await supabase
363	    .from('metas_vendas')
364	    .select('loja_id, dia_semana, valor_meta')
365	    .limit(1000);
366	  if (error) throw error;
367	  const out = new Map<string, number>();
368	  for (const row of data ?? []) {
369	    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
370	  }
371	  return out;
372	}
373	
374	function metaFor(
375	  metas: Map<string, number> | undefined,
376	  lojaId: number,
377	  date: Date,
378	): number | null {
379	  if (!metas) return null;
380	  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
381	}
382	
383	// ─────────────────────────────────────────────────────────────────────────────
384	// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
385	// ─────────────────────────────────────────────────────────────────────────────
386	
387	/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
388	export async function fetchStockAlerts(): Promise<StockRow[]> {
389	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
390	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
391	  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
392	  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
393	  //
394	  // `setor` vai junto no select: a regra do CTO 2026-06-05 (alertas SÓ do
395	  // setor TV_ALERT_SETOR = produtos vendáveis) é aplicada client-side com
396	  // normalização em `buildStockSummary` — a caixa/acento no banco é
397	  // inconsistente ("CÂMARA FRIA" vs "Câmara Fria"), então um `.eq` server-side
398	  // exato deixaria variantes legítimas de "Produtos" passarem/caírem errado.
399	  const data = await fetchAllPages((from, to) =>
400	    supabase
401	      .from('estoque')
402	      .select(
403	        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo, setor)',
404	      )
405	      .eq('produto_master.ativo', true)
406	      .gt('quantidade_minima', 0)
407	      .or('oculto.is.null,oculto.eq.false')
408	      .order('id')
409	      .range(from, to),
410	  );
411	  return data.map((row) => ({
412	    loja_id: row.loja_id,
413	    quantidade_atual: row.quantidade_atual,
414	    quantidade_minima: row.quantidade_minima,
415	    produtoNome: row.produto_master?.nome ?? '(sem nome)',
416	    setor: row.produto_master?.setor ?? null,
417	  }));
418	}
419	
420	// ─────────────────────────────────────────────────────────────────────────────
421	// Movimentações de hoje (heartbeat por loja)
422	// ─────────────────────────────────────────────────────────────────────────────
423	
424	async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
425	  const startOfDay = new Date();
426	  startOfDay.setHours(0, 0, 0, 0);
427	  // Pico real >1k movimentações/dia: paginar (PostgREST corta em 1000).
428	  const data = await fetchAllPages((from, to) =>
429	    supabase
430	      .from('movimentacoes')
431	      .select('loja_id, tipo_movimentacao, data_movimentacao')
432	      .gte('data_movimentacao', startOfDay.toISOString())
433	      .order('id')
434	      .range(from, to),
435	  );
436	  return aggregateMovements(data);
437	}
438	
439	// ─────────────────────────────────────────────────────────────────────────────
440	// Feed nomeado de movimentações de hoje (mini-feed "AGORA" por coluna)
441	// ─────────────────────────────────────────────────────────────────────────────
442	
443	/**
444	 * Quantas linhas o feed busca de uma vez. NÃO pagina de propósito: é um
445	 * feed "AGORA" (últimas {@link TV_MINI_FEED_SIZE} por unidade) — query
446	 * separada dos AGREGADOS (que seguem paginados via fetchAllPages). Em dia
447	 * de pico (acima de 150 movimentações) uma unidade parada há muitas horas
448	 * pode ficar sem mini-feed — aceitável: o card já mostra "última bipagem".
449	 */
450	const TV_FEED_FETCH_LIMIT = 150;
451	
452	/** Forma da linha de `movimentacoes` com o join de nome do produto. */
453	interface MovementFeedQueryRow {
454	  loja_id: number | null;
455	  tipo_movimentacao: string;
456	  data_movimentacao: string | null;
457	  quantidade: number | null;
458	  produto_master: { nome: string } | null;
459	}
460	
461	function toFeedRows(rows: MovementFeedQueryRow[]): MovementFeedRow[] {
462	  // Feed mostra TODA movimentação (evento operacional aconteceu, produto
463	  // ativo ou não) — diferente das listas de produto, que filtram ativo=true.
464	  return rows.map((r) => ({
465	    loja_id: r.loja_id,
466	    tipo_movimentacao: r.tipo_movimentacao,
467	    data_movimentacao: r.data_movimentacao,
468	    quantidade: r.quantidade,
469	    produtoNome: r.produto_master?.nome ?? '(sem produto)',
470	  }));
471	}
472	
473	async function fetchMovementFeed(): Promise<Map<number, TvRecentMove[]>> {
474	  const startOfDay = new Date();
475	  startOfDay.setHours(0, 0, 0, 0);
476	  const { data, error } = await supabase
477	    .from('movimentacoes')
478	    .select(
479	      'loja_id, tipo_movimentacao, data_movimentacao, quantidade, produto_master:produtos_master(nome)',
480	    )
481	    .gte('data_movimentacao', startOfDay.toISOString())
482	    .order('data_movimentacao', { ascending: false })
483	    .limit(TV_FEED_FETCH_LIMIT);
484	  if (error) throw error;
485	  return buildRecentMoves(toFeedRows(data ?? []), TV_MINI_FEED_SIZE);
486	}
487	
488	// ─────────────────────────────────────────────────────────────────────────────
489	// Perdas no período do filtro global (tabela `perdas`)
490	// ─────────────────────────────────────────────────────────────────────────────
491	
492	/** Par período corrente + período anterior equivalente (comparativo). */
493	export interface PeriodedAggregates<T> {
494	  current: T;
495	  previous: T;
496	}
497	
498	async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
499	  const bounds = rangeToLocalDayBounds(range);
500	  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
501	  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
502	  const rows = await fetchAllPages((from, to) =>
503	    supabase
504	      .from('perdas')
505	      .select('loja_id, valor_estimado')
506	      .gte('data_identificacao', bounds.startIso)
507	      .lt('data_identificacao', bounds.endExclusiveIso)
508	      .order('id')
509	      .range(from, to),
510	  );
511	  return aggregatePerdas(rows);
512	}
