527	// ─────────────────────────────────────────────────────────────────────────────
528	
529	async function loadComprasRange(range: TvDateRange): Promise<ComprasByLoja> {
530	  // Campo de data canônico: `data_nota` (emissão) — mesmo critério do DRE.
531	  // Status válido = tudo menos `erro` (NF_COUNTED_STATUSES); transferências
532	  // internas "Momma Doces" excluídas (não são compra). Paginado: um mês de
533	  // NFs pode passar de 1000 linhas.
534	  const rows = await fetchAllPages((from, to) =>
535	    supabase
536	      .from('notas_fiscais')
537	      .select('loja_id, valor_total')
538	      .gte('data_nota', range.from)
539	      .lte('data_nota', range.to)
540	      .in('status', [...NF_COUNTED_STATUSES])
541	      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
542	      .order('id')
543	      .range(from, to),
544	  );
545	  return aggregateCompras(rows);
546	}
