560	// Produção da fábrica (daily_production com loja_id NULL = fábrica)
561	// ─────────────────────────────────────────────────────────────────────────────
562	
563	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
564	  const today = toIsoDateLocal(new Date());
565	
566	  const loadDay = async (date: string) => {
567	    const { data, error } = await supabase
568	      .from('daily_production')
569	      .select('quantity')
570	      .is('loja_id', null)
571	      .eq('date', date)
572	      .limit(2000);
573	    if (error) throw error;
574	    return data ?? [];
575	  };
576	
577	  let refDate = today;
578	  let rows = await loadDay(today);
579	  if (rows.length === 0) {
580	    // Sem produção registrada hoje → mostra o último dia disponível
581	    const { data: latest, error } = await supabase
582	      .from('daily_production')
583	      .select('date')
584	      .is('loja_id', null)
585	      .lte('date', today)
586	      .order('date', { ascending: false })
587	      .limit(1);
588	    if (error) throw error;
589	    const lastDate = latest?.[0]?.date;
590	    if (!lastDate) return null;
591	    refDate = lastDate;
592	    rows = await loadDay(lastDate);
593	  }
594	
595	  return {
596	    dataReferencia: refDate,
597	    itens: rows.length,
598	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
599	  };
600	}
