606	/** Retorno do {@link useTvDashboardData}. */
607	export interface TvDashboardData {
608	  network: TvNetworkSummary | null;
609	  stores: TvStoreData[];
610	  factory: TvFactoryData | null;
611	  exceptions: TvExceptionsResult;
612	  freshness: TvFreshness;
613	  /** Período do filtro global aplicado a perdas/compras/comparativos. */
614	  period: TvPeriod;
