616	  range: TvDateRange;
617	  /** Range anterior equivalente usado nos comparativos. */
618	  previousRange: TvDateRange;
619	  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
620	  isLoading: boolean;
621	  /** true quando o contexto falhou (painel não consegue montar). */
622	  isError: boolean;
