625	const EMPTY_MOVEMENT: TvMovementSummary = {
626	  entradas: 0,
627	  saidas: 0,
628	  ultimaBipagem: null,
629	};
630	
631	const EMPTY_PERDAS_AGG: PerdasAggregate = { valor: 0, itens: 0 };
632	
633	/** Monta o resumo de perdas de UMA unidade a partir dos agregados. */
634	function perdasSummaryFor(
635	  agg: PeriodedAggregates<PerdasByLoja> | undefined,
636	  lojaId: number,
637	): TvPerdasSummary {
638	  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_PERDAS_AGG;
639	  const prev = agg?.previous.byLoja.get(lojaId);
640	  return {
641	    valor: cur.valor,
642	    itens: cur.itens,
643	    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
644	  };
645	}
646	
647	/** Monta o resumo de compras de UMA unidade a partir dos agregados. */
648	function comprasSummaryFor(
649	  agg: PeriodedAggregates<ComprasByLoja> | undefined,
650	  lojaId: number,
651	): TvComprasSummary {
652	  const cur = agg?.current.byLoja.get(lojaId) ?? 0;
653	  const prev = agg?.previous.byLoja.get(lojaId);
654	  return { valor: cur, deltaPct: relativeDelta(cur, prev ?? null) };
655	}
