657	/**
658	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
659	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
660	 * `freshness`). Vendas live re-buscam a cada 60s; o resto a
661	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
662	 *
663	 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
664	 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
665	 */
666	export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
667	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
668	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
669	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
670	  const tick = useMinuteClock();
671	
672	  const ctxQuery = useQuery({
673	    queryKey: tvDashboardKeys.context(),
674	    queryFn: fetchTvContext,
675	    staleTime: TV_QUERY_INTERVALS.slowMs,
676	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
677	  });
678	  const ctx = ctxQuery.data;
679	
680	  const liveQuery = useQuery({
681	    queryKey: tvDashboardKeys.liveSales(),
682	    queryFn: () => {
683	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
684	      return fetchLiveSales(ctx);
685	    },
686	    enabled: !!ctx,
687	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
688	    staleTime: 30_000,
689	  });
690	
691	  const laggedQuery = useQuery({
692	    queryKey: tvDashboardKeys.laggedSales(),
693	    queryFn: () => {
694	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
695	      return fetchLaggedSales(ctx);
696	    },
697	    enabled: !!ctx,
698	    staleTime: TV_QUERY_INTERVALS.slowMs,
699	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
700	  });
701	
702	  const referenceQuery = useQuery({
703	    queryKey: tvDashboardKeys.referenceSales(),
704	    queryFn: () => {
705	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
706	      return fetchDegustReference(ctx);
707	    },
708	    enabled: !!ctx,
709	    staleTime: TV_QUERY_INTERVALS.slowMs,
710	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
711	  });
712	
713	  const perdasQuery = useQuery({
714	    queryKey: tvDashboardKeys.perdas(period),
715	    queryFn: () => fetchPerdasAggregates(period),
716	    staleTime: TV_QUERY_INTERVALS.slowMs,
717	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
718	  });
719	
720	  const comprasQuery = useQuery({
721	    queryKey: tvDashboardKeys.compras(period),
722	    queryFn: () => fetchComprasAggregates(period),
723	    staleTime: TV_QUERY_INTERVALS.slowMs,
724	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
725	  });
726	
727	  const feedQuery = useQuery({
728	    queryKey: tvDashboardKeys.movementFeed(),
729	    queryFn: fetchMovementFeed,
730	    staleTime: TV_QUERY_INTERVALS.slowMs,
731	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
732	  });
733	
734	  const metasQuery = useQuery({
735	    queryKey: tvDashboardKeys.metas(),
736	    queryFn: fetchMetas,
737	    staleTime: TV_QUERY_INTERVALS.slowMs,
738	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
739	  });
740	
741	  const stockQuery = useQuery({
742	    queryKey: tvDashboardKeys.stock(),
743	    queryFn: fetchStockAlerts,
744	    staleTime: TV_QUERY_INTERVALS.slowMs,
745	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
746	  });
747	
748	  const movementsQuery = useQuery({
749	    queryKey: tvDashboardKeys.movements(),
750	    queryFn: fetchMovementsToday,
751	    staleTime: TV_QUERY_INTERVALS.slowMs,
752	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
753	  });
754	
755	  const factoryQuery = useQuery({
756	    queryKey: tvDashboardKeys.factoryProduction(),
757	    queryFn: fetchFactoryProduction,
758	    staleTime: TV_QUERY_INTERVALS.slowMs,
759	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
760	  });
761	
762	  return useMemo<TvDashboardData>(() => {
763	    const now = tick;
764	    const todayIso = toIsoDateLocal(now);
765	    const range = periodRange(period, now);
766	    const previousRange = previousPeriodRange(period, now);
767	
768	    const stockDetail: Map<number, StockDetail> = buildStockSummary(
769	      stockQuery.data ?? [],
770	    );
771	    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
772	    const feedByLoja = feedQuery.data ?? new Map<number, TvRecentMove[]>();
773	    const flashByLoja = new Map<number, FlashRow>(
774	      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
775	    );
776	    const laggedByLoja = new Map<number, LaggedSales>(
777	      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
778	    );
779	    const lastWeekByLoja = referenceQuery.data?.lastWeek ?? new Map<number, number>();
780	    const yesterdayByLoja = referenceQuery.data?.yesterday ?? new Map<number, number>();
781	    const perdasAgg = perdasQuery.data;
782	    const comprasAgg = comprasQuery.data;
783	    const lojaNomeById = new Map<number, string>(
784	      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
785	    );
786	
787	    // ── Cards de loja ──
788	    const stores: TvStoreData[] = (ctx?.lojas ?? [])
789	      .filter((l) => !isFactoryTipo(l.tipo))
790	      .map((loja) => {
791	        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
792	          ? 'degust-live'
793	          : 'linx-lagged';
794	        const stock = stockDetail.get(loja.id);
795	        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;
796	
797	        let vendas: TvSalesSnapshot | null = null;
798	        let metaDia: number | null = null;
799	        let pctMeta: number | null = null;
800	        let deltaSemana: number | null = null;
801	        let deltaOntem: number | null = null;
802	
803	        if (channel === 'degust-live') {
804	          const flash = flashByLoja.get(loja.id);
805	          if (flash) {
806	            vendas = {
807	              valor: flash.total_vendas,
808	              cupons: flash.total_cupons,
809	              ticketMedio: flash.ticket_medio,
810	              dataReferencia: todayIso,
811	              isLive: true,
812	              caixaAberto: flash.caixa_aberto,
813	              atualizadoEm: flash.ultima_atualizacao,
814	            };
815	            metaDia = metaFor(metasQuery.data, loja.id, now);
816	            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
817	            // Deltas live = "vs MESMO PONTO do dia de referência": a base
818	            // (ontem = PRINCIPAL v3; semana passada = secundário) é
819	            // pró-rateada pela fração da janela já decorrida (mesma fração
820	            // do pró-rata da meta). Comparar hoje PARCIAL com dia COMPLETO
821	            // inflava a queda de manhã.
822	            deltaOntem = relativeDelta(
823	              flash.total_vendas,
824	              proRataDayBase(yesterdayByLoja.get(loja.id) ?? null, now),
825	            );
826	            deltaSemana = weekOverWeekDelta(
827	              flash.total_vendas,
828	              proRataDayBase(lastWeekByLoja.get(loja.id) ?? null, now),
829	            );
830	          }
831	        } else {
832	          const lagged = laggedByLoja.get(loja.id);
833	          if (lagged) {
834	            vendas = {
835	              valor: lagged.valor,
836	              cupons: null,
837	              ticketMedio: null,
838	              dataReferencia: lagged.dataReferencia,
839	              isLive: false,
840	              caixaAberto: null,
841	              atualizadoEm: null,
842	            };
843	            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
844	            const refDate = parseIsoDateLocal(lagged.dataReferencia);
845	            metaDia = metaFor(metasQuery.data, loja.id, refDate);
846	            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
847	            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
848	            // Principal v3 = vs dia ANTERIOR ao de referência.
849	            deltaOntem = relativeDelta(lagged.valor, lagged.valorDiaAnterior);
850	            deltaSemana = weekOverWeekDelta(
851	              lagged.valor,
852	              lagged.valorSemanaAnterior,
853	            );
854	          }
855	        }
856	
857	        const rag = classifyStoreRag({
858	          stockOutCount: stock?.zerados ?? 0,
859	          stockLowCount: stock?.abaixoMinimo ?? 0,
860	          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
861	          isLiveChannel: channel === 'degust-live',
862	          lastMovementAt: movement.ultimaBipagem,
863	          now,
864	        });
865	
866	        return {
867	          lojaId: loja.id,
868	          nome: loja.nome,
869	          channel,
870	          vendas,
871	          metaDia,
872	          pctMeta,
873	          deltaSemana,
874	          deltaOntem,
875	          estoque: {
876	            zerados: stock?.zerados ?? 0,
877	            abaixoMinimo: stock?.abaixoMinimo ?? 0,
878	          },
879	          movimentacao: movement,
880	          perdas: perdasSummaryFor(perdasAgg, loja.id),
881	          compras: comprasSummaryFor(comprasAgg, loja.id),
882	          criticalItems: sortCriticalItems(stock?.itens ?? []),
883	          recentMoves: feedByLoja.get(loja.id) ?? [],
884	          rag: rag.status,
885	          ragReasons: rag.reasons,
886	        };
887	      });
888	
889	    // ── Card da fábrica ──
890	    let factory: TvFactoryData | null = null;
891	    if (ctx?.factoryLojaId != null) {
892	      const fid = ctx.factoryLojaId;
893	      const stock = stockDetail.get(fid);
894	      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
895	      const rag = classifyStoreRag({
896	        stockOutCount: stock?.zerados ?? 0,
897	        stockLowCount: stock?.abaixoMinimo ?? 0,
898	        pctMetaProRata: null,
899	        isLiveChannel: false,
900	        lastMovementAt: movement.ultimaBipagem,
901	        now,
902	        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
903	        hours: TV_FACTORY_HOURS,
904	        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
905	      });
906	      factory = {
907	        lojaId: fid,
908	        nome: lojaNomeById.get(fid) ?? 'Fábrica',
909	        producao: factoryQuery.data ?? null,
910	        expedicoes: movement,
911	        estoque: {
912	          zerados: stock?.zerados ?? 0,
913	          abaixoMinimo: stock?.abaixoMinimo ?? 0,
914	        },
915	        perdas: perdasSummaryFor(perdasAgg, fid),
916	        compras: comprasSummaryFor(comprasAgg, fid),
917	        criticalItems: sortCriticalItems(stock?.itens ?? []),
918	        recentMoves: feedByLoja.get(fid) ?? [],
919	        rag: rag.status,
920	        ragReasons: rag.reasons,
921	      };
922	    }
923	
924	    // ── Freshness ──
925	    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
926	    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
927	    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
928	    const freshness: TvFreshness = buildFreshness(
929	      liveQuery.dataUpdatedAt,
930	      stockQuery.dataUpdatedAt,
931	      TV_QUERY_INTERVALS,
932	      now,
933	    );
934	
935	    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
936	    const allExceptions: TvException[] = buildStockExceptions(
937	      stockDetail,
938	      lojaNomeById,
939	    );
940	    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
941	    // janela), nunca por parsing de ragReasons — independe da cor do card
942	    // (aparece mesmo com card vermelho) e cobre também a fábrica.
943	    for (const store of stores) {
944	      const noMovement = buildNoMovementException({
945	        lojaId: store.lojaId,
946	        lojaNome: store.nome,
947	        lastMovementAt: store.movimentacao.ultimaBipagem,
948	        now,
949	      });
950	      if (noMovement) allExceptions.push(noMovement);
951	    }
952	    if (factory) {
953	      const noMovement = buildNoMovementException({
954	        lojaId: factory.lojaId,
955	        lojaNome: factory.nome,
956	        lastMovementAt: factory.expedicoes.ultimaBipagem,
957	        now,
958	        hours: TV_FACTORY_HOURS,
959	        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
960	      });
961	      if (noMovement) allExceptions.push(noMovement);
962	    }
963	    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
964	      const liveUpdatedAt = freshness.vendasLive.updatedAt;
965	      allExceptions.push({
966	        id: 'stale-data:vendas-live',
967	        kind: 'stale-data',
968	        severity: 'amber',
969	        lojaId: null,
970	        lojaNome: null,
971	        message: liveUpdatedAt
972	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
973	          : 'Venda live ainda não carregou',
974	      });
975	    }
976	    const exceptions = sortAndLimitExceptions(allExceptions);
977	
978	    // ── Hero (rede) ──
979	    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
980	    const liveStores = stores.filter(
981	      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
982	    );
983	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
984	    const metasHoje = liveStores
985	      .map((s) => s.metaDia)
986	      .filter((m): m is number => m != null && m > 0);
987	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
988	    const lastWeekTotal = liveStores.reduce(
989	      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
990	      0,
991	    );
992	    const yesterdayTotal = liveStores.reduce(
993	      (s, st) => s + (yesterdayByLoja.get(st.lojaId) ?? 0),
994	      0,
995	    );
996	    const network: TvNetworkSummary | null = ctx
997	      ? {
998	          vendasHoje,
999	          metaDia,
1000	          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
1001	          // Mesmo critério do card live: deltas "vs mesmo ponto do dia de
1002	          // referência" (base pró-rateada pela fração da janela). Ontem é
1003	          // o PRINCIPAL (v3); semana passada segue como secundário.
1004	          deltaSemana: weekOverWeekDelta(
1005	            vendasHoje,
1006	            proRataDayBase(lastWeekTotal, now),
1007	          ),
1008	          deltaOntem: relativeDelta(
1009	            vendasHoje,
1010	            proRataDayBase(yesterdayTotal, now),
1011	          ),
1012	          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
1013	          // nenhuma coluna — entram SOMENTE aqui).
1014	          perdas: {
1015	            valor: perdasAgg?.current.total.valor ?? 0,
1016	            itens: perdasAgg?.current.total.itens ?? 0,
1017	            deltaPct: relativeDelta(
1018	              perdasAgg?.current.total.valor ?? 0,
1019	              perdasAgg?.previous.total.valor ?? null,
1020	            ),
1021	          },
1022	          compras: {
1023	            valor: comprasAgg?.current.total ?? 0,
1024	            deltaPct: relativeDelta(
1025	              comprasAgg?.current.total ?? 0,
1026	              comprasAgg?.previous.total ?? null,
1027	            ),
1028	          },
1029	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
1030	          lojasLive: liveStores.length,
1031	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
1032	        }
1033	      : null;
1034	
1035	    return {
1036	      network,
1037	      stores,
1038	      factory,
1039	      exceptions,
1040	      freshness,
1041	      period,
1042	      range,
1043	      previousRange,
1044	      isLoading: ctxQuery.isLoading,
1045	      isError: ctxQuery.isError,
